using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Text;using Microsoft.VisualBasic.FileIO;using RecepcionDocumental.Configuration;using RecepcionDocumental.Infrastructure;using RecepcionDocumental.Services;
namespace PdfRasterProbe{
internal static class H1D9EShadowProductProbe{
internal static int Run(string[]a){if(a.Length!=5){Console.Error.WriteLine("Uso: --h1d9e-shadow-product <dataset.csv> <h1d8b-product-regression.csv> <h1d9d1c-onnx-parity.csv> <output>");return 2;}try{return Execute(a);}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
static int Execute(string[]a){var dataset=Read(a[1]);var old=Read(a[2]).ToDictionary(x=>x["Sha256"],x=>x["H1D8B"],StringComparer.OrdinalIgnoreCase);var reference=Read(a[3]).ToDictionary(x=>x["Sha256"],x=>x,StringComparer.OrdinalIgnoreCase);var output=Path.GetFullPath(a[4]);Directory.CreateDirectory(output);var root=Path.Combine(Path.GetTempPath(),"RecepcionDocumental-H1D9E-"+Guid.NewGuid().ToString("N"));var config=new ConfiguracionAplicacion("RecepcionDocumental",Path.Combine(root,"Logs"),Path.Combine(root,"Trabajo"),Path.Combine(root,"Facturas"),Path.Combine(root,"Revisar"),200,52428800,262144000,3,"https://localhost/h1d9e",true,"H1D9B-CANDIDATE-001");config.PrepararRutasOperativas();ConfiguracionSistema.Inicializar(config);Logs.Inicializar(config);var rows=new List<R>();try{foreach(var d in dataset){var path=d["Path"];if(!Path.IsPathRooted(path))path=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Path.GetFullPath(a[1])),path));Console.WriteLine("H1D9E | "+(rows.Count+1)+"/80 | "+d["Sha256"]);using(var w=new AttachmentWorkspace()){var x=DocumentAnalysisService.Analyze(File.ReadAllBytes(path),Path.GetFileName(path),Mime(path),w);var c=x.Candidates.FirstOrDefault();var classification=c==null?"DESCARTAR":c.Selection.Classification;var v=c==null?null:c.VisualShadow;var rr=new R{Sha=d["Sha256"],Expected=old[d["Sha256"]],Actual=classification,V=v,Rasterizations=c==null?0:c.PdfRasterizationCount,OcrPages=c==null?0:c.PdfPagesRenderedForOcr,ShadowPages=c==null?0:c.PdfPagesRenderedForShadow,FirstRendered=c!=null&&c.PdfFirstPageRenderedByOcr,FirstReused=c!=null&&c.PdfFirstPageReusedByShadow};if(v!=null&&v.Status=="OK"&&reference.ContainsKey(rr.Sha)){rr.Reference=double.Parse(reference[rr.Sha]["CSharpPFactura"],CultureInfo.InvariantCulture);rr.Delta=Math.Abs(v.PFactura.Value-rr.Reference);rr.ReferenceZone=reference[rr.Sha]["ZoneEqual"]=="true"?Zone(rr.Reference):"INVALID";}rows.Add(rr);}}}
finally{if(Directory.Exists(root))Directory.Delete(root,true);}Write(output,rows);var eligible=rows.Where(x=>x.Actual!="DESCARTAR").ToList();var duplicates=rows.Count(x=>x.FirstRendered&&x.ShadowPages>0);var ok=rows.Count==80&&rows.All(x=>x.Expected==x.Actual)&&eligible.Count==70&&eligible.All(x=>x.V!=null&&x.V.Attempted&&x.V.Status=="OK")&&eligible.All(x=>x.Delta<=.00005&&x.V.Zone==Zone(x.Reference))&&rows.Where(x=>x.Actual=="DESCARTAR").All(x=>x.V==null)&&duplicates==0&&VisualInvoiceShadowService.SessionsCreated==1;Console.WriteLine("H1D9E | Eligible="+eligible.Count+" | OK="+eligible.Count(x=>x.V!=null&&x.V.Status=="OK")+" | Changed="+rows.Count(x=>x.Expected!=x.Actual)+" | DuplicateFirstPage="+duplicates+" | SessionsCreated="+VisualInvoiceShadowService.SessionsCreated+" | Process64Bit="+Environment.Is64BitProcess+" | Gate="+ok);return ok?0:1;}
static void Write(string o,List<R>x){var e=x.Where(v=>v.Actual!="DESCARTAR").ToList();var normal=new[]{"Sha256,ExpectedClassification,ActualClassification,Changed,Attempted,Status,Zone,PFactura,VisualSource,RasterReused,PdfRasterizations"}.Concat(x.Select(v=>J(v.Sha,v.Expected,v.Actual,B(v.Expected!=v.Actual),B(v.V!=null&&v.V.Attempted),v.V==null?"":v.V.Status,v.V==null?"":v.V.Zone,v.V==null||!v.V.PFactura.HasValue?"":F(v.V.PFactura.Value),v.V==null?"":v.V.VisualSource,B(v.V!=null&&v.V.RasterReused),v.Rasterizations.ToString()))).ToArray();File.WriteAllLines(Path.Combine(o,"product-shadow-enabled.csv"),normal,new UTF8Encoding(false));File.WriteAllLines(Path.Combine(o,"normal-regression.csv"),normal,new UTF8Encoding(false));File.WriteAllLines(Path.Combine(o,"visual-parity.csv"),new[]{"Sha256,ReferencePFactura,ProductPFactura,AbsDelta,PredEqual,ZoneEqual"}.Concat(e.Select(v=>J(v.Sha,F(v.Reference),F(v.V.PFactura.Value),F(v.Delta),B((v.Reference>=.5)==(v.V.PFactura>=.5)),B(Zone(v.Reference)==v.V.Zone)))),new UTF8Encoding(false));var accounting=new[]{"Sha256,VisualSource,RasterReused,PdfRasterizerCalls,PdfPagesRenderedForOcr,PdfPagesRenderedForShadow,FirstPageRenderedByOcr,FirstPageReusedByShadow,DuplicateFirstPage"}.Concat(x.Select(v=>J(v.Sha,v.V==null?"":v.V.VisualSource,B(v.V!=null&&v.V.RasterReused),v.Rasterizations.ToString(),v.OcrPages.ToString(),v.ShadowPages.ToString(),B(v.FirstRendered),B(v.FirstReused),B(v.FirstRendered&&v.ShadowPages>0)))).ToArray();File.WriteAllLines(Path.Combine(o,"raster-accounting.csv"),accounting,new UTF8Encoding(false));File.WriteAllLines(Path.Combine(o,"raster-reuse.csv"),accounting,new UTF8Encoding(false));File.WriteAllText(Path.Combine(o,"performance.md"),"# Performance H1D9E1A\n\n- Decode ms total: "+e.Sum(v=>v.V.DecodeMilliseconds??0)+".\n- Resize ms total: "+e.Sum(v=>v.V.ResizeMilliseconds??0)+".\n- Normalización ms total: "+e.Sum(v=>v.V.NormalizeMilliseconds??0)+".\n- ONNX ms total: "+e.Sum(v=>v.V.OnnxMilliseconds??0)+".\n- Total ms: "+e.Sum(v=>v.V.TotalMilliseconds??0)+".\n",new UTF8Encoding(false));}
static List<Dictionary<string,string>>Read(string p){var z=new List<Dictionary<string,string>>();using(var q=new TextFieldParser(p,Encoding.UTF8)){q.SetDelimiters(",");q.HasFieldsEnclosedInQuotes=true;var h=q.ReadFields();while(!q.EndOfData){var f=q.ReadFields();var r=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<h.Length;i++)r[h[i]]=f[i];z.Add(r);}}return z;}static string Mime(string p){var x=Path.GetExtension(p).ToLowerInvariant();return x==".pdf"?"application/pdf":x==".png"?"image/png":"image/jpeg";}static string Zone(double p){return p<=VisualInvoiceShadowService.TNoFactura?"NO_FACTURA_FUERTE":p>=VisualInvoiceShadowService.TFactura?"FACTURA_FUERTE":"INCIERTO_VISUAL";}static string F(double x){return x.ToString("0.#########",CultureInfo.InvariantCulture);}static string B(bool x){return x?"true":"false";}static string J(params string[]x){return string.Join(",",x.Select(v=>"\""+(v??"").Replace("\"","\"\"")+"\""));}sealed class R{public string Sha,Expected,Actual,ReferenceZone;public VisualShadowResult V;public double Reference,Delta;public int Rasterizations,OcrPages,ShadowPages;public bool FirstRendered,FirstReused;}
}}
